(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      textLayerName: ${textLayerName},
      duration: ${duration},
      intensity: ${intensity},
      bounceCount: ${bounceCount},
      baseScale: ${baseScale},
      color: ${color}
    };
    var layer = comp.layers.byName(p.textLayerName);
    if (!layer) {
      var nt = comp.layers.addText(p.textLayerName);
      nt.name = p.textLayerName;
      layer = nt;
    }
    var sc = layer.property("Scale");
    var t0 = layer.inPoint;
    var dt = p.duration / (p.bounceCount + 1);
    sc.setValueAtTime(t0, [p.baseScale * 0.3, p.baseScale * 0.3]);
    for (var i = 0; i < p.bounceCount; i++) {
      var peak = p.baseScale * p.intensity;
      sc.setValueAtTime(t0 + dt * (i + 0.5), [peak, peak]);
      sc.setValueAtTime(t0 + dt * (i + 1), [p.baseScale, p.baseScale]);
    }
    for (var k = 1; k <= sc.numKeys; k++) {
      sc.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    var src = layer.property("Source Text");
    var td = src.value;
    td.fillColor = p.color;
    td.fontSize = 120;
    td.fauxBold = true;
    td.justification = ParagraphJustification.CENTER;
    src.setValue(td);
    _result = {status:"success", message:"抖音弹跳标题动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
