      glitchIntensity: ${glitchIntensity},
      rgbShift: ${rgbShift},
      scanlineOpacity: ${scanlineOpacity}
    };
    var layer = comp.layers.byName(p.textLayerName);
    if (!layer) {
      var nt = comp.layers.addText(p.textLayerName);
      nt.name = p.textLayerName;
      layer = nt;
    }
    var textProp = layer.property("ADBE Text Properties");
    var animator = textProp.property("ADBE Text Animators").addProperty("ADBE Text Animator");
    var rangeSel = animator.property("ADBE Text Selectors").addProperty("ADBE Text Selector");
    var posProp = animator.property("ADBE Text Animator Properties").addProperty("ADBE Position");
    var opacityProp = animator.property("ADBE Text Animator Properties").addProperty("ADBE Opacity");
