    if (!layer) {
      var nt = comp.layers.addText(p.textLayerName);
      nt.name = p.textLayerName;
      layer = nt;
    }
    var src = layer.property("Source Text");
    var td = src.value;
    td.fillColor = p.metalColor;
    td.strokeColor = p.shadowColor;
    td.strokeWidth = 1;
    td.applyStroke = true;
    td.applyFill = true;
    src.setValue(td);
    var bevel = layer.Effects.addProperty("ADBE Bevel Alpha");
    bevel.property("ADBE Bevel Alpha-0002").setValue(p.bevelDepth);
    bevel.property("ADBE Bevel Alpha-0003").setValue(45);
    bevel.property("ADBE Bevel Alpha-0005").setValue(p.highlightColor);
    bevel.property("ADBE Bevel Alpha-0006").setValue(p.shadowColor);
    var curve = layer.Effects.addProperty("ADBE Curves");
    var curveProp = curve.property("ADBE Curves-0005");
    curveProp.setValue([0, 0, 255, 255]);
    var shine = layer.Effects.addProperty("ADBE Glo2i");
    shine.property("ADBE Glo2i-0001").setValue(p.highlightColor);
    shine.property("ADBE Glow Radius-0001").setValue(p.shineAmount * 0.3);
    shine.property("ADBE Glo2i-0003").setValue(2);
